exercises.solution_md:
```systemverilog
module xor_assign (input logic a, b, output logic y);
    assign y = a ^ b;
endmodule

module xor_comb (input logic a, b, output logic y);
    always_comb begin
        if (a == b)
            y = 1'b0;
        else
            y = 1'b1;
    end
endmodule

module tb_xor;
    logic a, b, y1, y2;
    int errors = 0;
    xor_assign u1 (.a(a), .b(b), .y(y1));
    xor_comb   u2 (.a(a), .b(b), .y(y2));
    initial begin
        for (int i = 0; i < 4; i++) begin
            {a, b} = i;
            #10;
            $display("a=%b b=%b -> %b %b", a, b, y1, y2);
            if (y1 !== y2) errors++;
        end
        if (errors == 0) $display("OK: same truth table");
        else             $display("ERROR: %0d differences", errors);
        $finish;
    end
endmodule
```

**אמור להופיע:** 4 שורות ואז `OK: same truth table` (נבדק ב-Icarus Verilog).
